//! File-type icons: a glyph of the bundled "Harlo File Icons" font (cut
//! from Nerd Fonts by `tools/file-icons.py`) in the type's colour.
//!
//! [`icon`] picks the glyph and colour for a file name.

// Rust guideline compliant 2026-10-09

// Generated by `tools/file-icons.py`, so left as the script writes it.
#[rustfmt::skip]
#[expect(clippy::unreadable_literal, reason = "colours as the generator writes them, 0xrrggbb")]
mod glyphs;

use glyphs::GLYPHS;

/// The type shown for a file nothing else matches.
const FALLBACK: &str = "document";

/// The colour used if even the fallback type were missing from the table.
const FALLBACK_COLOR: u32 = 0x0090_a4ae;

/// A file's icon: a glyph of the "Harlo File Icons" font and its colour as
/// `0xrrggbb`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FileIcon {
    /// The glyph.
    pub glyph: char,
    /// Its colour, as `0xrrggbb`.
    pub color: u32,
}

impl FileIcon {
    /// The colour as Slint's.
    #[must_use]
    pub fn slint_color(self) -> slint::Color {
        let [_, r, g, b] = self.color.to_be_bytes();
        slint::Color::from_rgb_u8(r, g, b)
    }
}

fn glyph(id: &str) -> Option<FileIcon> {
    GLYPHS
        .binary_search_by(|(k, _, _)| (*k).cmp(id))
        .ok()
        .map(|i| FileIcon {
            glyph: GLYPHS[i].1,
            color: GLYPHS[i].2,
        })
}

fn known(id: &str) -> bool {
    glyph(id).is_some()
}

/// Whole file names (lowercase) with an icon of their own.
fn by_file_name(name: &str) -> Option<&'static str> {
    Some(match name {
        "dockerfile"
        | "containerfile"
        | "docker-compose.yml"
        | "docker-compose.yaml"
        | "compose.yml"
        | "compose.yaml"
        | ".dockerignore" => "docker",
        "makefile" | "gnumakefile" => "makefile",
        "cmakelists.txt" => "cmake",
        "meson.build" => "meson",
        "justfile" | ".justfile" => "just",
        "package.json" | "package-lock.json" | ".npmrc" | ".npmignore" => "npm",
        "yarn.lock" | ".yarnrc" | ".yarnrc.yml" => "yarn",
        "pnpm-lock.yaml" | "pnpm-workspace.yaml" => "pnpm",
        "bun.lock" | "bun.lockb" | "bunfig.toml" => "bun",
        // (Cargo's files are TOML and a lock file, not Rust code.)
        "cargo.lock" => "lock",
        "go.mod" | "go.sum" | "go.work" => "go-mod",
        "gemfile" | "gemfile.lock" => "gemfile",
        "rakefile" | "podfile" | "vagrantfile" | "brewfile" => "ruby",
        "pyproject.toml" | "requirements.txt" | "setup.py" | "setup.cfg" | "pipfile"
        | "pipfile.lock" | ".python-version" => "python-misc",
        "poetry.lock" => "poetry",
        "uv.lock" => "uv",
        "tsconfig.json" => "tsconfig",
        "jsconfig.json" => "jsconfig",
        ".gitignore"
        | ".gitattributes"
        | ".gitmodules"
        | ".gitkeep"
        | ".git-blame-ignore-revs"
        | ".mailmap" => "git",
        ".editorconfig" => "editorconfig",
        ".prettierrc" | ".prettierignore" | "prettier.config.js" => "prettier",
        ".eslintrc" | ".eslintignore" | "eslint.config.js" | "eslint.config.mjs" => "eslint",
        ".babelrc" | "babel.config.js" => "babel",
        ".nvmrc" | ".node-version" => "nodejs",
        "license" | "license.md" | "license.txt" | "licence" | "copying" | "unlicense" => {
            "certificate"
        }
        "readme" | "readme.md" | "readme.txt" => "readme",
        "changelog" | "changelog.md" | "changes.md" | "history.md" => "changelog",
        "contributing.md" => "contributing",
        "code_of_conduct.md" => "conduct",
        "authors" | "authors.md" | "contributors" => "authors",
        "codeowners" => "codeowners",
        "security.md" => "verified",
        "todo" | "todo.md" => "todo",
        "claude.md" => "claude",
        "agents.md" => "markdown",
        "caddyfile" => "caddy",
        "procfile" => "heroku",
        "robots.txt" => "robots",
        "flake.nix" | "flake.lock" | "default.nix" | "shell.nix" => "nix",
        "vite.config.ts" | "vite.config.js" | "vite.config.mjs" => "vite",
        "vitest.config.ts" | "vitest.config.js" => "vitest",
        "tailwind.config.js" | "tailwind.config.ts" => "tailwindcss",
        "postcss.config.js" | "postcss.config.cjs" | "postcss.config.mjs" => "postcss",
        "renovate.json" => "renovate",
        "biome.json" | "biome.jsonc" => "biome",
        "turbo.json" => "turborepo",
        "vercel.json" => "vercel",
        "netlify.toml" => "netlify",
        "deno.json" | "deno.jsonc" => "deno",
        "knip.json" => "knip",
        ".env" => "tune",
        _ => return None,
    })
}

